// Extract lead data from Voiceflow
const leadData = {
  // Contact Information
  name: $input.item.json.lead_name || 'Unknown',
  email: $input.item.json.email || '',

  // Travel Details
  travelDates: $input.item.json.travel_dates || 'Not specified',
  groupSize: parseInt($input.item.json.group_size) || 0,
  needPermits: $input.item.json.need_permits || 'Not asked',

  // Scoring & Intent
  leadScore: parseInt($input.item.json.lead_score) || 0,
  sessionId: $input.item.json.session_id || 'voiceflow_' + Date.now(),

  // Metadata
  source: 'voiceflow',
  timestamp: $input.item.json.timestamp || new Date().toISOString(),
  conversationTranscript: $input.item.json.conversation_transcript || []
};

// Parse conversation to detect additional signals
const transcript = typeof leadData.conversationTranscript === 'string' 
  ? leadData.conversationTranscript 
  : JSON.stringify(leadData.conversationTranscript);

const transcriptLower = transcript.toLowerCase();

// Enhanced intent detection
const intents = {
  booking: /\b(book|reserve|availability)\b/i.test(transcript),
  pricing: /\b(cost|price|expensive|how much)\b/i.test(transcript),
  permits: /\b(permit|gorilla permit)\b/i.test(transcript),
  accommodation: /\b(room|accommodation|stay|lodge)\b/i.test(transcript),
  activities: /\b(activities|things to do|what else)\b/i.test(transcript),
  packing: /\b(pack|bring|wear)\b/i.test(transcript),
  timing: /\b(when|best time|season)\b/i.test(transcript)
};

// Extract additional data from conversation
let extractedData = {
  hasSpecificDates: leadData.travelDates !== 'Not specified',
  hasGroupSize: leadData.groupSize > 0,
  hasEmail: leadData.email !== '',

  // Detect special requests
  honeymoon: /\b(honeymoon|wedding|anniversary)\b/i.test(transcript),
  familyTrip: /\b(family|kids|children)\b/i.test(transcript),
  soloTraveler: leadData.groupSize === 1,
  largeGroup: leadData.groupSize >= 6,

  // Detect urgency
  urgentBooking: /\b(urgent|soon|asap|next week|next month)\b/i.test(transcript),
  flexible: /\b(flexible|any time|whenever)\b/i.test(transcript)
};

// Calculate enhanced lead score
let finalScore = leadData.leadScore;

// Boost for complete information
if (extractedData.hasEmail) finalScore += 25;
if (extractedData.hasSpecificDates) finalScore += 20;
if (extractedData.hasGroupSize) finalScore += 15;

// Boost for urgency
if (extractedData.urgentBooking) finalScore += 20;

// Boost for special occasions (high-value)
if (extractedData.honeymoon) finalScore += 15;

// Cap at 100
finalScore = Math.min(finalScore, 100);

// Determine priority
let priority = 'low';
let routingDestination = 'nurture_campaign';
let expectedResponseTime = '48 hours';

if (finalScore >= 80) {
  priority = 'high';
  routingDestination = 'senior_booking_agent';
  expectedResponseTime = '1 hour';
} else if (finalScore >= 50) {
  priority = 'medium';
  routingDestination = 'travel_planning_specialist';
  expectedResponseTime = '24 hours';
}

// Determine which agent (simulation)
const agents = {
  senior_booking_agent: [
    { id: 'SBA-001', name: 'Sarah Mitchell', email: 'sarah@sambora.com', available: true },
    { id: 'SBA-002', name: 'James Uwimana', email: 'james@sambora.com', available: true }
  ],
  travel_planning_specialist: [
    { id: 'TPS-001', name: 'Michael Ngabo', email: 'michael@sambora.com', available: true },
    { id: 'TPS-002', name: 'Grace Mukankusi', email: 'grace@sambora.com', available: true }
  ]
};

const agentPool = agents[routingDestination] || [];
const selectedAgent = agentPool.find(a => a.available) || {
  id: 'QUEUE',
  name: 'Next Available',
  email: 'reservations@sambora.com'
};

// Prepare output
return {
  json: {
    // Lead Information
    leadName: leadData.name,
    email: leadData.email,
    travelDates: leadData.travelDates,
    groupSize: leadData.groupSize,
    needPermits: leadData.needPermits,

    // Scoring
    leadScore: finalScore,
    priority: priority,

    // Intent Analysis
    intents: intents,
    extractedData: extractedData,

    // Routing
    routingDestination: routingDestination,
    assignedAgent: selectedAgent,
    expectedResponseTime: expectedResponseTime,

    // Metadata
    source: 'voiceflow',
    sessionId: leadData.sessionId,
    timestamp: leadData.timestamp,
    conversationTranscript: leadData.conversationTranscript,

    // For Google Sheets
    receivedAt: new Date().toISOString(),
    status: 'new',

    // Quick summary for notifications
    summary: `${leadData.name} ${extractedData.hasEmail ? '(' + leadData.email + ')' : '(no email)'} - ${leadData.groupSize} people - ${leadData.travelDates}`
  }
};

